          ],
          "items": {
            "type": "object",
            "description": "日历日程项。",
            "sampleValue": {
              "entityName": "calendar",
              "entityId": "calendar-event-001",
              "title": "产品评审",
              "dtStart": "09:30",
              "dtEnd": "10:00"
            },
            "properties": {
              "entityName": {
                "type": "string",
                "description": "内容类别。",
                "sampleValue": "calendar"
              },
              "entityId": {
                "type": "string",
                "description": "日程唯一标识符。",
                "sampleValue": "calendar-event-001"
              },
              "title": {
                "type": "string",
                "description": "日程标题。",
                "sampleValue": "产品评审"
              },
              "dtStart": {
                "type": "string",
                "description": "日程开始时间，当天日程为 HH:MM 格式。",
                "sampleValue": "09:30"
              },
              "dtEnd": {
                "type": "string",
                "description": "日程结束时间，当天日程为 HH:MM 格式。",
                "sampleValue": "10:00"
              }
            }
          }
        }
      }
    },
    "ui": {
      "title": {
        "type": "string",
        "description": "卡片标题。",
        "sampleValue": "待办清单"
      },
      "statusText": {
        "type": "string",
        "description": "完成状态文案。",
        "sampleValue": "已完成"
      },
      "actionLabel": {
        "type": "string",
        "description": "打开应用的短按钮文案。",
        "sampleValue": "打开"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/checkmark_calendar_fill.svg",
      "description": "带对勾的日历实心图标，适合表达已完成日程和日程确认状态。"
    }
  ]
}

